package repository;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.ConcurrentHashMap;import model.annotation.Id;public class Repository<T>{private final Map<String,T> data=new ConcurrentHashMap<>();private String idOf(T x){for(Field f:x.getClass().getDeclaredFields())if(f.isAnnotationPresent(Id.class)){try{f.setAccessible(true);return String.valueOf(f.get(x));}catch(Exception e){throw new IllegalStateException(e);}}throw new IllegalArgumentException("Entity has no @Id field");}public T save(T x){data.put(idOf(x),x);return x;}@SafeVarargs public final void saveAll(T...xs){for(T x:xs)save(x);}public T findById(String id){return data.get(id);}public ArrayList<T> findAll(){return new ArrayList<>(data.values());}public boolean delete(String id){return data.remove(id)!=null;}public int size(){return data.size();}}
